import Link from 'next/link'

type Eq = { label: string; formula: string; variables: string; interpretation: string; assumptions: string; kind: string; example?: string }
type Section = { number: string; title: string; paragraphs: string[]; bullets?: string[]; table?: { caption: string; heads: string[]; rows: string[][] } }

function MathFormula({ kind }: { kind: string }) {
  const t = (v: string) => <mi>{v}</mi>
  if (kind === 'utilization') return <math aria-label="utilization"><mrow>{t('Utilization')}<mo>=</mo><mfrac>{t('Actual Output')}{t('Design Capacity')}</mfrac><mo>×</mo><mn>100</mn><mo>%</mo></mrow></math>
  if (kind === 'efficiency') return <math aria-label="efficiency"><mrow>{t('Efficiency')}<mo>=</mo><mfrac>{t('Actual Output')}{t('Effective Capacity')}</mfrac><mo>×</mo><mn>100</mn><mo>%</mo></mrow></math>
  if (kind === 'eoq') return <math aria-label="economic order quantity"><mrow><msub><mi>Q</mi><mi>EOQ</mi></msub><mo>=</mo><msqrt><mfrac><mrow><mn>2</mn><mi>DS</mi></mrow><mi>H</mi></mfrac></msqrt></mrow></math>
  if (kind === 'rop') return <math aria-label="reorder point"><mrow><mi>ROP</mi><mo>=</mo><mrow><mi>d</mi><mo>×</mo><mi>L</mi></mrow><mo>+</mo><mi>SS</mi></mrow></math>
  if (kind === 'little') return <math aria-label="Little's law"><mrow>{t('WIP')}<mo>=</mo>{t('Throughput')}<mo>×</mo>{t('Flow Time')}</mrow></math>
  if (kind === 'line') return <math aria-label="line efficiency"><mrow><mi>Efficiency</mi><mo>=</mo><mfrac><mi>Σ Task Time</mi><mrow><mi>Number of Stations</mi><mo>×</mo><mi>Cycle Time</mi></mrow></mfrac><mo>×</mo><mn>100</mn><mo>%</mo></mrow></math>
  if (kind === 'bullwhip') return <math aria-label="bullwhip ratio"><mrow><mi>BR</mi><mo>=</mo><mfrac><mi>Variance of Orders</mi><mi>Variance of Demand</mi></mfrac></mrow></math>
  if (kind === 'mtbf') return <math aria-label="mean time between failures"><mrow><mi>MTBF</mi><mo>=</mo><mfrac><mi>Total Operating Time</mi><mi>Number of Failures</mi></mfrac></mrow></math>
  if (kind === 'standard') return <math aria-label="standard time"><mrow><mi>ST</mi><mo>=</mo><mi>NT</mi><mo>×</mo><mrow><mo>(</mo><mn>1</mn><mo>+</mo><mi>Allowance</mi><mo>)</mo></mrow></mrow></math>
  return <math aria-label="normal time"><mrow><mi>NT</mi><mo>=</mo><mi>Observed Time</mi><mo>×</mo><mi>Rating Factor</mi></mrow></math>
}



function TableBlock({ table }: { table: NonNullable<Section['table']> }) { return <div className="skill-table-section"><table><caption>{table.caption}</caption><thead><tr>{table.heads.map((head) => <th key={head}>{head}</th>)}</tr></thead><tbody>{table.rows.map((row) => <tr key={row[0]}>{row.map((cell) => <td key={cell}>{cell}</td>)}</tr>)}</tbody></table></div> }

const equations: Eq[] = [
  { label: 'Utilization', kind: 'utilization', formula: 'Actual Output / Design Capacity × 100%', variables: 'Actual Output = unit nyata yang dihasilkan; Design Capacity = output maksimum teoritis dalam kondisi ideal.', interpretation: 'Mengukur intensitas penggunaan kapasitas desain. Utilization tinggi tidak selalu berarti proses efisien karena downtime dan kualitas belum diperhitungkan.', assumptions: 'Kedua kapasitas berada pada periode, unit, dan definisi produk yang sama.', },
  { label: 'Efficiency', kind: 'efficiency', formula: 'Actual Output / Effective Capacity × 100%', variables: 'Effective Capacity = kapasitas desain setelah dikurangi maintenance terencana, setup, dan batas operasional lain.', interpretation: 'Mengukur seberapa baik kapasitas yang benar-benar tersedia dimanfaatkan.', assumptions: 'Downtime terencana didefinisikan konsisten dan actual output telah dikurangi unit cacat bila analisis mensyaratkannya.', },
  { label: 'Economic Order Quantity', kind: 'eoq', formula: 'Q_EOQ = √(2DS/H)', variables: 'D = permintaan tahunan; S = biaya pemesanan per order; H = biaya penyimpanan tahunan per unit; Q = kuantitas per order.', interpretation: 'Titik minimum teoritis antara biaya pemesanan dan biaya penyimpanan tahunan.', assumptions: 'Demand dan lead time deterministik, replenishment seketika, tidak ada stockout, harga unit konstan, dan biaya dapat diestimasi.', },
  { label: 'Reorder Point', kind: 'rop', formula: 'ROP = d × L + SS', variables: 'd = permintaan rata-rata per satuan waktu; L = lead time; SS = safety stock.', interpretation: 'Menentukan kapan pesanan baru dilepas agar persediaan tiba sebelum stok habis.', assumptions: 'Demand dan lead time memiliki basis waktu yang sama; safety stock ditentukan dari tingkat layanan dan variabilitas.', },
  { label: 'Little’s Law', kind: 'little', formula: 'WIP = Throughput × Flow Time', variables: 'WIP = work in process; Throughput = rata-rata output per waktu; Flow Time = waktu rata-rata berada di sistem.', interpretation: 'Menghubungkan inventori proses, laju keluaran, dan waktu aliran dalam sistem yang relatif stabil.', assumptions: 'Sistem berada pada kondisi steady state dan tidak terjadi akumulasi WIP tak terbatas.', },
  { label: 'Line Efficiency', kind: 'line', formula: 'Σ Task Time / (Stations × Cycle Time) × 100%', variables: 'Task Time = waktu seluruh tugas; Stations = jumlah workstation; Cycle Time = waktu maksimum yang tersedia per unit.', interpretation: 'Menunjukkan proporsi waktu tersedia yang terisi oleh pekerjaan bernilai proses.', assumptions: 'Precedence task dipatuhi, cycle time didefinisikan jelas, dan waktu setup atau allowance diperlakukan konsisten.', },
  { label: 'Bullwhip Ratio', kind: 'bullwhip', formula: 'Variance of Orders / Variance of Demand', variables: 'Variance of Orders = varians pesanan pada tingkat rantai pasok; Variance of Demand = varians permintaan pelanggan.', interpretation: 'Nilai lebih besar dari satu menunjukkan amplifikasi variabilitas ketika bergerak ke hulu.', assumptions: 'Varians dihitung pada horizon, unit, dan periode observasi yang sebanding.', },
  { label: 'Mean Time Between Failures', kind: 'mtbf', formula: 'Total Operating Time / Number of Failures', variables: 'Total Operating Time = waktu operasi kumulatif; Number of Failures = jumlah kegagalan yang didefinisikan.', interpretation: 'Indikator reliabilitas aset repairable; bukan probabilitas langsung bahwa mesin akan hidup pada waktu tertentu.', assumptions: 'Kegagalan, waktu operasi, dan periode observasi dicatat konsisten.', },
  { label: 'Normal Time', kind: 'normal', formula: 'NT = Observed Time × Rating Factor', variables: 'Observed Time = rata-rata waktu siklus; Rating Factor = penilaian kecepatan relatif terhadap pace normal.', interpretation: 'Menormalkan hasil pengamatan terhadap tingkat kinerja operator.', assumptions: 'Rating dilakukan oleh analis terlatih dan elemen kerja yang diamati merepresentasikan metode standar.', },
  { label: 'Standard Time', kind: 'standard', formula: 'ST = NT × (1 + Allowance)', variables: 'ST = waktu standar; NT = normal time; Allowance = kelonggaran personal, fatigue, dan unavoidable delay.', interpretation: 'Waktu yang ditetapkan untuk pekerjaan normal dengan kelonggaran kerja yang wajar.', assumptions: 'Basis allowance dinyatakan jelas; delay yang dapat dihindari tidak dimasukkan sebagai standar.', },
]


