const workedExamples: Record<string, { title: string; steps: string[]; result: string }> = {
  '01': { title: 'OEE dan load ratio — satu work centre', steps: ['Waktu produksi terencana = 420 menit; run time = 360 menit; total count = 180; good count = 171; ideal cycle = 2 menit.', 'Availability = 360 / 420 = 85,7%; Performance = (2 × 180) / 360 = 100%; Quality = 171 / 180 = 95,0%.', 'Beban CRP yang dibutuhkan = 460 menit dibandingkan dengan 420 menit yang tersedia.'], result: 'OEE = 85,7% × 100% × 95,0% = 81,4%; load ratio = 460 / 420 = 109,5%, sehingga work centre mengalami overload.' },
  '02': { title: 'MPS → POH → ATP', steps: ['Persediaan awal = 60 unit. Forecast: 90 / 110 / 100. Pesanan pelanggan: 80 / 120 / 70. MPS: 100 / 120 / 100.', 'POH₁ = 60 + 100 − 90 = 70; POH₂ = 70 + 120 − 120 = 70; POH₃ = 70 + 100 − 100 = 70.', 'ATP pada periode 1 = 60 + 100 − 80 = 80 unit sebelum penerimaan MPS berikutnya.'], result: 'Rencana mempertahankan projected balance sebesar 70 unit sekaligus menyisakan 80 unit yang masih dapat dijanjikan pada periode 1.' },
  '03': { title: 'EOQ dan reorder point', steps: ['D = 10.000 unit/tahun; S = $40/order; H = $2/unit-tahun. EOQ = √(2 × 10.000 × 40 / 2) = 632 unit.', 'Biaya pemesanan tahunan = (10.000 / 632) × $40 ≈ $632; biaya penyimpanan tahunan = (632 / 2) × $2 ≈ $632.', 'Permintaan rata-rata = 40 unit/hari; lead time = 5 hari; safety stock = 60 unit.'], result: 'ROP = 40 × 5 + 60 = 260 unit. EOQ menyeimbangkan biaya pemesanan dan penyimpanan; ROP melindungi tingkat layanan.' },
  '04': { title: 'Biaya menunggu M/M/1', steps: ['Arrival rate λ = 8 pelanggan/jam; service rate μ = 10/jam; utilisasi ρ = 0,8.', 'L = 8 / (10 − 8) = 4 pelanggan; Lq = 8² / [10(10 − 8)] = 3,2 pelanggan.', 'W = 1 / (10 − 8) = 0,5 jam; Wq = 0,4 jam; P₀ = 0,2; P₃ = (1 − 0,8) × 0,8³ = 0,1024.'], result: 'Perubahan kapasitas layanan selama dua menit dapat menurunkan waktu tunggu secara material karena kurvanya non-linear ketika ρ mendekati 1.' },
  '05': { title: 'Line balancing', steps: ['Waktu tugas = 42 menit; kebutuhan output memerlukan 6 stasiun; cycle time = 8 menit.', 'Jumlah minimum stasiun secara teoritis = ceil(42 / 8) = 6. Efficiency = 42 / (6 × 8) = 87,5%.', 'Balance delay = 12,5%; precedence dan ergonomi tetap perlu divalidasi.'], result: 'Lini layak secara numerik, tetapi layout akhir harus memeriksa precedence, perpindahan, pemeriksaan kualitas, dan keselamatan.' },
  '06': { title: 'Alokasi transportasi', steps: ['Dua pabrik mengirim ke dua pasar. Misalkan xᵢⱼ adalah unit yang dikirim dan cᵢⱼ adalah biaya per unit.', 'Objective: minimalkan 4x₁₁ + 6x₁₂ + 5x₂₁ + 3x₂₂, dengan batasan supply dan demand.', 'Evaluasi alokasi optimal terhadap waktu layanan, reliabilitas, dan emisi—bukan biaya saja.'], result: 'Model transportasi memberi baseline biaya minimum; keputusan operasional menambahkan batasan kelayakan dan ketahanan.' },
  '07': { title: 'Reliabilitas Weibull', steps: ['β = 2, η = 1.000 jam, t = 500 jam. R(t) = exp[−(500/1.000)²].', 'R(500) = exp(−0,25) ≈ 0,779. Untuk MTBF ≈ ηΓ(1 + 1/β) ≈ 886 jam dan MTTR = 4 jam:', 'Availability ≈ 886 / (886 + 4) = 99,55%.'], result: 'Reliability pada mission time dan availability steady-state menjawab pertanyaan yang berbeda; jangan menggantikan yang satu dengan yang lain.' },
  '08': { title: 'Time study dan work sampling', steps: ['Observed time = 5,2 menit; rating = 1,10; allowance = 15%. Normal time = 5,2 × 1,10 = 5,72 menit.', 'Standard time = 5,72 × 1,15 = 6,578 menit. Untuk work sampling, 138 observasi produktif dari 200 menghasilkan p̂ = 69%.', 'Untuk p = 0,70, z = 1,96, e = 0,05: n = z²p(1−p)/e² ≈ 323 observasi.'], result: 'Standar dapat ditelusuri ke metode, rating, allowance, dan tingkat keyakinan sampel—bukan sekadar rata-rata stopwatch.' },
}

